// @ts-nocheck

// Indexed min-heap specialized for Fortune circle events. Ordering is strict
// lexicographic on (yBottom, x), which matters because site coords are seeded
// from a 16-bit randomizer: ties on yBottom are common in practice and must
// be ordered deterministically.
//
// The comparison is inlined (no virtual lessThan() call) for non-JIT
// platforms; this is why the class is a standalone implementation rather
// than a subclass of IndexedMinHeap. Likewise, the backing typed arrays and
// `size` are exposed as public fields so hot loops can read the root via
// `heap.y[0]` / `heap.x[0]` / `heap.indices[0]` without a method dispatch.

export class CircleEventHeap {
	y: Float64Array;
	x: Float64Array;
	indices: Uint32Array;
	size = 0;

	constructor(initialSize: number) {
		initialSize = Math.max(1, initialSize);
		this.y = new Float64Array(initialSize);
		this.x = new Float64Array(initialSize);
		this.indices = new Uint32Array(initialSize);
	}

	push(y: number, x: number, index: number): void {
		if (this.size >= this.y.length) {
			const newCap = this.y.length * 2;
			const newY = new Float64Array(newCap);
			const newX = new Float64Array(newCap);
			const newIndices = new Uint32Array(newCap);
			newY.set(this.y);
			newX.set(this.x);
			newIndices.set(this.indices);
			this.y = newY;
			this.x = newX;
			this.indices = newIndices;
		}
		this.y[this.size] = y;
		this.x[this.size] = x;
		this.indices[this.size] = index;
		this.bubbleUp(this.size);
		this.size++;
	}

	pop(): void {
		if (this.size === 0) return;
		--this.size;
		if (this.size > 0) {
			this.y[0] = this.y[this.size];
			this.x[0] = this.x[this.size];
			this.indices[0] = this.indices[this.size];
			this.bubbleDown(0);
		}
	}

	clear(): void {
		this.size = 0;
	}

	private swap(i: number, j: number): void {
		const ty = this.y[i];
		this.y[i] = this.y[j];
		this.y[j] = ty;
		const tx = this.x[i];
		this.x[i] = this.x[j];
		this.x[j] = tx;
		const ti = this.indices[i];
		this.indices[i] = this.indices[j];
		this.indices[j] = ti;
	}

	private bubbleUp(index: number): void {
		const y = this.y;
		const x = this.x;
		while (index > 0) {
			const parent = (index - 1) >> 1;
			const yi = y[index],
				yp = y[parent];
			if (yi > yp || (yi === yp && x[index] >= x[parent])) break;
			this.swap(index, parent);
			index = parent;
		}
	}

	private bubbleDown(index: number): void {
		const length = this.size;
		const y = this.y;
		const x = this.x;
		while (true) {
			const left = 2 * index + 1;
			const right = left + 1;
			let smallest = index;
			let ys = y[smallest];
			let xs = x[smallest];

			if (left < length) {
				const yl = y[left];
				if (yl < ys || (yl === ys && x[left] < xs)) {
					smallest = left;
					ys = yl;
					xs = x[left];
				}
			}
			if (right < length) {
				const yr = y[right];
				if (yr < ys || (yr === ys && x[right] < xs)) {
					smallest = right;
				}
			}
			if (smallest === index) break;

			this.swap(index, smallest);
			index = smallest;
		}
	}
}
